styles.content:
/* Deltron-only native form recipes. Tokens are generated from ../brand/profile.json. */
:root{font-family:var(--font-sans);font-synthesis:none;color:var(--dt-gray);background:var(--dt-page)}
*{box-sizing:border-box}body{margin:0;background:var(--dt-page);color:var(--dt-gray);font-family:var(--font-sans);line-height:1.5}a{color:var(--dt-blue)}button,input,select{font:inherit}button,a,input,select{touch-action:manipulation}button{cursor:pointer}[hidden]{display:none!important}:focus-visible{outline:3px solid var(--dt-blue);outline-offset:4px}h1,h2,h3{font-weight:500}h1{font-size:clamp(2rem,1.5rem + 1.2vw,2.75rem);line-height:1.2;margin:0 0 1rem}h2{font-size:1.5rem}p{overflow-wrap:anywhere}
.dt-skip{position:absolute;top:-6rem;left:1rem;z-index:20;background:var(--surface-card);padding:.75rem 1rem;border:1px solid var(--dt-line);border-radius:var(--dt-radius)}.dt-skip:focus{top:1rem}
.dt-site-header{background:var(--surface-card);border-bottom:1px solid var(--dt-line)}.dt-header{width:min(var(--dt-content-max),calc(100% - 3rem));min-height:7rem;display:flex;gap:2rem;align-items:center;margin:auto}.dt-brand{display:inline-flex;align-items:center;width:var(--dt-logo-width);padding:var(--dt-logo-pad);margin-right:auto;flex-shrink:0}.dt-brand img{object-fit:contain;width:100%;height:auto}.dt-logo-dark{display:none}:root[data-theme=dark] .dt-logo-light{display:none}:root[data-theme=dark] .dt-logo-dark{display:block}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]):not([data-theme=dark]) .dt-logo-light{display:none}:root:not([data-theme=light]):not([data-theme=dark]) .dt-logo-dark{display:block}}
.dt-header nav a{display:inline-flex;align-items:center;min-height:44px;text-decoration:none;font-size:.875rem;font-weight:500;padding:.5rem 0;color:var(--dt-gray)}.dt-header nav a[aria-current=page]{color:var(--dt-blue);text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:.5rem}.dt-theme{display:flex;align-items:center;gap:.5rem;font-size:.75rem}.dt-theme select{min-height:44px;border:1px solid var(--dt-gray);border-radius:var(--dt-radius);padding:.5rem 2rem .5rem .75rem;background:var(--surface-card);color:var(--dt-gray);font-size:.875rem}
.dt-button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;border:1px solid var(--dt-blue-fill);border-radius:var(--dt-radius);padding:.75rem 1.5rem;background:var(--dt-blue-fill);color:#fff;font-size:.875rem;font-weight:500;text-decoration:none;box-shadow:var(--dt-shadow-primary);transition:box-shadow var(--dt-transition)}.dt-button:hover{box-shadow:var(--dt-shadow-hover)}.dt-button:disabled{opacity:.65;cursor:default;box-shadow:none}.dt-account{position:relative;flex-shrink:0}.dt-account summary{list-style:none;display:flex;align-items:center;gap:.75rem;cursor:pointer;font-size:.875rem;min-height:44px}.dt-account summary::-webkit-details-marker{display:none}.dt-avatar{display:grid;place-items:center;width:2.5rem;height:2.5rem;border-radius:50%;background:var(--dt-blue-soft);color:var(--dt-blue);font-size:.75rem;font-weight:500}.dt-account-panel{position:absolute;z-index:10;right:0;top:calc(100% + .75rem);width:15rem;background:var(--surface-card);border:1px solid var(--dt-line);border-radius:var(--dt-radius-card);padding:.75rem;box-shadow:var(--dt-shadow-dialog)}.dt-account-panel>a,.dt-account-panel>button{display:block;min-height:44px;width:100%;border:0;background:transparent;color:var(--dt-gray);text-decoration:none;text-align:left;padding:.75rem;font-size:.875rem;border-radius:var(--dt-radius)}.dt-account-panel>a:hover,.dt-account-panel>button:hover{background:var(--dt-hover)}.dt-account-panel>p{margin:0 .75rem .5rem;font-size:.75rem}
.dt-main{min-height:calc(100vh - 12rem)}.dt-warranty{width:min(var(--dt-content-max),calc(100% - 3rem));margin:3rem auto}.dt-page-heading{max-width:48rem;margin-bottom:2rem}.dt-eyebrow{font-size:.75rem;font-weight:500;letter-spacing:.08em;color:var(--dt-blue);margin:0 0 .75rem}.dt-muted{color:var(--dt-gray);font-size:1rem;line-height:1.6;margin:0}.dt-form{background:var(--surface-card);border:1px solid var(--dt-line);border-radius:var(--dt-radius-card);padding:2rem;box-shadow:var(--dt-shadow-card)}.dt-form fieldset{border:0;padding:0;margin:0 0 2rem;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem;min-width:0}.dt-form legend{width:100%;padding:0 0 1rem;margin:0 0 1.5rem;border-bottom:1px solid var(--dt-line);font-size:1.125rem;font-weight:500;color:var(--dt-gray)}.dt-field{min-width:0;display:flex;flex-direction:column;gap:.5rem}.dt-field label{font-size:.875rem;line-height:1.5;font-weight:500}.dt-required{color:var(--dt-blue);margin-left:.25rem}.dt-control{width:100%;min-width:0;min-height:48px;padding:.75rem;border:1px solid var(--dt-gray);border-radius:var(--dt-radius);background:var(--surface-card);color:var(--dt-gray);font-size:1rem;box-shadow:var(--dt-shadow-control)}.dt-control[aria-invalid=true]{border-color:var(--danger)}.dt-control[type=file]{font-size:.875rem;padding:.5rem;cursor:pointer}.dt-control::file-selector-button{border:0;border-radius:var(--dt-radius);background:var(--dt-blue-soft);color:var(--dt-blue);padding:.5rem .75rem;margin-right:.75rem;font:inherit;font-weight:500;cursor:pointer}.dt-help,.dt-field-error{font-size:.75rem;line-height:1.5;margin:0}.dt-help{color:var(--dt-gray)}.dt-field-error{color:var(--danger)}.dt-field-wide{grid-column:1/-1}.dt-check{display:grid;grid-template-columns:18px minmax(0,1fr);align-items:start;column-gap:.75rem}.dt-check .dt-checkbox{appearance:auto;display:block;box-sizing:border-box;width:18px;height:18px;min-width:18px;min-height:18px;padding:0;margin:13px 0 0;accent-color:var(--dt-blue-fill);cursor:pointer}.dt-check .dt-checkbox[aria-invalid=true]{outline:1px solid var(--danger);outline-offset:2px}.dt-check label{display:block;min-height:44px;padding-block:.75rem;margin:0;line-height:20px;cursor:pointer}.dt-check>div{display:grid;min-width:0;gap:.25rem}.dt-check label .dt-required{align-self:center}.dt-actions{border-top:1px solid var(--dt-line);padding-top:1.5rem;display:flex;align-items:center;gap:1.5rem;justify-content:space-between}.dt-actions>p{font-size:.75rem}.dt-status{font-size:.875rem;line-height:1.6;white-space:pre-wrap}.dt-error{color:var(--danger)}.dt-notice{border-left:3px solid var(--dt-blue);padding:.75rem 1rem;background:var(--dt-blue-soft);color:var(--dt-gray);font-size:.875rem;line-height:1.6;margin:0 0 1.5rem}.dt-success{padding:2rem;background:var(--success-subtle);color:var(--success);border:1px solid var(--success);border-radius:var(--dt-radius-card)}
.dt-login{width:min(30rem,calc(100% - 3rem));margin:3rem auto;background:var(--surface-card);border:1px solid var(--dt-line);border-radius:var(--dt-radius-card);padding:2rem;box-shadow:var(--dt-shadow-card)}.dt-login [data-dt-login]{margin-top:1.5rem;--front-auth-width:100%;--front-auth-button-bg:var(--dt-blue-fill);--front-auth-button-text:#fff;--front-auth-radius:var(--dt-radius);--text:var(--dt-gray);--muted:var(--dt-gray);--line:var(--dt-gray);--panel:var(--surface-card);--panel-raised:var(--surface-card);--accent:var(--dt-blue);--accent-strong:var(--dt-blue-fill)}.dt-login .elastyc-front-auth .efa-input{min-height:48px;font-size:1rem}.dt-login .elastyc-front-auth button{min-height:44px;font-weight:500}.dt-login .elastyc-front-auth label{font-weight:500}.dt-back{display:inline-flex;align-items:center;min-height:44px;margin-top:1rem;font-size:.875rem;text-decoration:none}.dt-footer{border-top:1px solid var(--dt-line);padding:1.5rem;color:var(--dt-gray);font-size:.75rem;text-align:center}.dt-field .iti{width:100%;--iti-dropdown-bg:var(--surface-card);--iti-text-color:var(--dt-gray);--iti-hover-color:var(--dt-hover);--iti-border-color:var(--dt-line)}.dt-field .iti input{padding-left:90px}.dt-login .efa-root{padding:0}.dt-login [data-efa-view=account]{overflow-wrap:anywhere}.dt-field .dt-help:empty,.dt-field-error:empty{display:none}.dt-protection{display:grid;justify-items:start;gap:.5rem;margin:0 0 1.5rem;max-width:100%}.dt-protection-widget{width:300px;min-height:65px;max-width:100%}.dt-protection-retry{min-height:44px;padding:.5rem 0;border:0;background:transparent;color:var(--dt-blue);font-size:.875rem;text-decoration:underline}
@media(max-width:62rem){.dt-header{gap:1rem}.dt-header nav{margin-left:auto}.dt-theme>span{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}}
@media(max-width:44rem){.dt-header{width:calc(100% - 2rem);display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.5rem 1rem;padding:.75rem 0}.dt-brand{width:var(--dt-logo-width-sm);max-width:100%;grid-row:1;grid-column:1}.dt-account{grid-row:1;grid-column:2}.dt-header nav{grid-row:2;grid-column:1;margin:0}.dt-theme{grid-row:2;grid-column:2;justify-content:end}.dt-theme select{max-width:8rem}.dt-button{padding:.75rem 1rem}.dt-warranty{width:calc(100% - 2rem);margin:2rem auto}.dt-form{padding:1.5rem 1rem}.dt-form fieldset{grid-template-columns:1fr;gap:1.5rem}.dt-actions{align-items:stretch;flex-direction:column;gap:.5rem}.dt-actions .dt-button{width:100%}.dt-login{margin:2rem auto;padding:1.5rem}.dt-account summary>[data-dt-name]{max-width:6rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}
@media(max-width:420px){.dt-protection-widget{width:150px;min-height:140px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
@media(forced-colors:active){.dt-button,.dt-control,.dt-account-panel{border:1px solid ButtonText;box-shadow:none}.dt-checkbox{forced-color-adjust:auto}}

.dt-login .dt-form{padding:0;border:0;box-shadow:none}.dt-login .dt-form>.dt-field{margin-bottom:1rem}

/* FrontAuth may load its stylesheet after the theme; keep this tenant host explicit. */
html body{background:var(--dt-page);color:var(--dt-gray);font-family:var(--font-sans)}
.dt-login h1{color:var(--dt-gray);font-weight:500}
.dt-login .elastyc-front-auth .efa-field input{min-height:48px;padding:.75rem;border:1px solid var(--dt-gray);border-radius:var(--dt-radius);background:var(--surface-card);color:var(--dt-gray);font:inherit;box-shadow:var(--dt-shadow-control)}
.dt-login .elastyc-front-auth .efa-field input:focus-visible{outline:3px solid var(--dt-blue);outline-offset:4px}
.dt-login .elastyc-front-auth .efa-form button{min-height:44px;font-family:var(--font-sans);font-weight:500}

.dt-login .elastyc-front-auth .efa-field label{color:var(--dt-gray);font-weight:500}
